// Package graph defines the schema and persistence layer for the
// `entire understand` fused graph (structural + history + semantic).
package graph

import "time"

// SchemaVersion is the on-disk schema version for understand artifacts.
// Bump on any breaking change to the persisted format. Readers must check this
// against the version they understand and refuse to use a higher version.
const SchemaVersion = 1

// NodeType enumerates the node kinds that can appear in the fused graph.
type NodeType string

const (
	NodeRepo       NodeType = "repo"
	NodeDirectory  NodeType = "directory"
	NodeFile       NodeType = "file"
	NodeModule     NodeType = "module"
	NodePackage    NodeType = "package"
	NodeSymbol     NodeType = "symbol"
	NodeDomain     NodeType = "domain"
	NodeFlow       NodeType = "flow"
	NodeStep       NodeType = "step"
	NodePattern    NodeType = "pattern"
	NodeCheckpoint NodeType = "checkpoint"
	NodeSession    NodeType = "session"
)

// SymbolKind narrows a NodeSymbol to a specific role. Empty for non-symbol nodes.
type SymbolKind string

const (
	SymbolFunction  SymbolKind = "function"
	SymbolMethod    SymbolKind = "method"
	SymbolType      SymbolKind = "type"
	SymbolInterface SymbolKind = "interface"
	SymbolClass     SymbolKind = "class"
	SymbolStruct    SymbolKind = "struct"
	SymbolTest      SymbolKind = "test"
	SymbolConfig    SymbolKind = "config"
	SymbolDocument  SymbolKind = "document"
)

// EdgeType enumerates the relations that can appear between graph nodes.
type EdgeType string

const (
	EdgeContains        EdgeType = "contains"
	EdgeImports         EdgeType = "imports"
	EdgeCalls           EdgeType = "calls"
	EdgeImplements      EdgeType = "implements"
	EdgeReferences      EdgeType = "references"
	EdgeBelongsTo       EdgeType = "belongs_to"
	EdgePartOfFlow      EdgeType = "part_of_flow"
	EdgeRealizesPattern EdgeType = "realizes_pattern"
	EdgeTouchedIn       EdgeType = "touched_in"
	EdgeIntroducedIn    EdgeType = "introduced_in"
	EdgeModifiedIn      EdgeType = "modified_in"
	EdgeExplainedBy     EdgeType = "explained_by"
	EdgePrecedes        EdgeType = "precedes"
)

// Scope captures how authoritative a checkpoint→symbol attribution is.
//
// ScopeSymbol is reserved for deterministic evidence (diff overlap with a
// symbol's line range, tool telemetry pointing at a symbol, observed
// introduction/removal during timeline replay). ScopeFileOwner is used when
// the checkpoint touched the symbol's owning file but no symbol-level evidence
// exists; UI/CLI rendering must qualify these as "(file-level inferred)".
type Scope string

const (
	ScopeSymbol    Scope = "symbol"
	ScopeFileOwner Scope = "file-owner"
)

// SemanticStatus captures whether the agent-assisted stage ran successfully.
type SemanticStatus string

const (
	SemanticOK      SemanticStatus = "ok"
	SemanticSkipped SemanticStatus = "skipped"
	SemanticPartial SemanticStatus = "partial"
)

// Node is one entity in the fused graph. ID is stable across builds; consumers
// must not assume any other field is stable.
type Node struct {
	ID         string         `json:"id"`
	Type       NodeType       `json:"type"`
	SymbolKind SymbolKind     `json:"symbol_kind,omitempty"`
	Name       string         `json:"name"`
	Path       string         `json:"path,omitempty"`     // repo-relative (forward-slash)
	Language   string         `json:"language,omitempty"` // best-effort language guess
	LineStart  int            `json:"line_start,omitempty"`
	LineEnd    int            `json:"line_end,omitempty"`
	Attrs      map[string]any `json:"attrs,omitempty"`
}

// Edge is a directed relation From → To.
type Edge struct {
	ID    string         `json:"id"`
	From  string         `json:"from"`
	To    string         `json:"to"`
	Type  EdgeType       `json:"type"`
	Scope Scope          `json:"scope,omitempty"`
	Attrs map[string]any `json:"attrs,omitempty"`
}

// Manifest is the build summary written at .entire/understand/manifest.json.
type Manifest struct {
	SchemaVersion      int            `json:"schema_version"`
	BuildID            string         `json:"build_id"`
	BuiltAt            time.Time      `json:"built_at"`
	RepoFingerprint    string         `json:"repo_fingerprint"`
	CheckpointHead     string         `json:"checkpoint_head,omitempty"`
	StructuralStatus   string         `json:"structural_status"` // "ok"|"skipped"|"error"
	HistoryStatus      string         `json:"history_status"`
	SemanticStatus     SemanticStatus `json:"semantic_status"`
	SemanticReason     string         `json:"semantic_reason,omitempty"`
	SemanticProvider   string         `json:"semantic_provider,omitempty"`
	SemanticModel      string         `json:"semantic_model,omitempty"`
	SupportedLanguages []string       `json:"supported_languages"`
	NodeCount          int            `json:"node_count"`
	EdgeCount          int            `json:"edge_count"`
}

package graph

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
)

// CacheDirName is the repo-relative directory that holds understand artifacts.
// Mirrors `.entire/`, treated as a local cache subtree (gitignored).
const CacheDirName = ".entire/understand"

// Artifact filenames inside CacheDirName.
const (
	manifestFile   = "manifest.json"
	structuralFile = "structural.json"
	historyFile    = "history.json"
	semanticFile   = "semantic.json"
	timelineFile   = "timeline.json"
)

// Store persists understand artifacts under a repo's cache directory.
//
// The store does NOT make any assumptions about whether the underlying directory
// is committed; callers are responsible for adding the directory to .gitignore.
type Store struct {
	root string // absolute path to .entire/understand/
}

// NewStore returns a Store rooted at <repoRoot>/.entire/understand/.
// repoRoot must be an absolute path; the directory is not created until a
// write operation runs.
func NewStore(repoRoot string) *Store {
	return &Store{root: filepath.Join(repoRoot, CacheDirName)}
}

// Root returns the absolute path of the cache directory.
func (s *Store) Root() string { return s.root }

// Exists reports whether the cache directory and a manifest exist.
// A bare empty directory does not count.
func (s *Store) Exists() bool {
	_, err := os.Stat(filepath.Join(s.root, manifestFile))
	return err == nil
}

// Reset removes the entire cache directory. Returns nil if it doesn't exist.
func (s *Store) Reset() error {
	if err := os.RemoveAll(s.root); err != nil {
		return fmt.Errorf("reset understand cache: %w", err)
	}
	return nil
}

// WriteManifest persists the build manifest atomically.
func (s *Store) WriteManifest(m *Manifest) error {
	if m == nil {
		return errors.New("nil manifest")
	}
	if m.SchemaVersion == 0 {
		m.SchemaVersion = SchemaVersion
	}
	return s.writeJSON(manifestFile, m)
}

// ReadManifest loads the build manifest.
func (s *Store) ReadManifest() (*Manifest, error) {
	var m Manifest
	if err := s.readJSON(manifestFile, &m); err != nil {
		return nil, err
	}
	if m.SchemaVersion > SchemaVersion {
		return nil, fmt.Errorf("understand cache schema_version=%d is newer than supported (%d); rebuild required", m.SchemaVersion, SchemaVersion)
	}
	return &m, nil
}

// GraphSlice is a minimal serializable form for the structural / history /
// semantic / timeline files. Each layer writes its own slice; readers fuse
// them at query time.
type GraphSlice struct {
	Nodes []Node `json:"nodes"`
	Edges []Edge `json:"edges"`
}

// WriteStructural persists the deterministic structural slice.
func (s *Store) WriteStructural(slice *GraphSlice) error {
	return s.writeJSON(structuralFile, sliceOrEmpty(slice))
}

// ReadStructural loads the structural slice. Returns an empty slice when the
// file is missing — callers can treat absence as "build hasn't run yet".
func (s *Store) ReadStructural() (*GraphSlice, error) {
	return s.readSlice(structuralFile)
}

// WriteHistory persists the history fusion slice.
func (s *Store) WriteHistory(slice *GraphSlice) error {
	return s.writeJSON(historyFile, sliceOrEmpty(slice))
}

// ReadHistory loads the history slice. Missing file → empty slice.
func (s *Store) ReadHistory() (*GraphSlice, error) {
	return s.readSlice(historyFile)
}

// WriteSemantic persists the agent-assisted semantic slice.
func (s *Store) WriteSemantic(slice *GraphSlice) error {
	return s.writeJSON(semanticFile, sliceOrEmpty(slice))
}

// ReadSemantic loads the semantic slice. Missing file → empty slice.
func (s *Store) ReadSemantic() (*GraphSlice, error) {
	return s.readSlice(semanticFile)
}

// TimelineEvent is one step in the time-ordered replay.
type TimelineEvent struct {
	At           string         `json:"at"` // RFC3339
	CheckpointID string         `json:"checkpoint_id,omitempty"`
	SessionID    string         `json:"session_id,omitempty"`
	Kind         string         `json:"kind"` // "introduced"|"modified"|"removed"|"checkpoint"
	NodeIDs      []string       `json:"node_ids,omitempty"`
	Attrs        map[string]any `json:"attrs,omitempty"`
}

// Timeline is the persisted event stream for replay/time-slider.
type Timeline struct {
	Events []TimelineEvent `json:"events"`
}

// WriteTimeline persists the timeline events.
func (s *Store) WriteTimeline(t *Timeline) error {
	if t == nil {
		t = &Timeline{}
	}
	if t.Events == nil {
		t.Events = []TimelineEvent{}
	}
	return s.writeJSON(timelineFile, t)
}

// ReadTimeline loads the timeline. Missing file → empty timeline.
func (s *Store) ReadTimeline() (*Timeline, error) {
	var t Timeline
	if err := s.readJSON(timelineFile, &t); err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return &Timeline{Events: []TimelineEvent{}}, nil
		}
		return nil, err
	}
	if t.Events == nil {
		t.Events = []TimelineEvent{}
	}
	return &t, nil
}

// FusedGraph returns the union of structural, history, and semantic slices.
// Duplicate node IDs are de-duplicated keeping the first occurrence (structural
// wins over history wins over semantic) so deterministic data takes precedence.
func (s *Store) FusedGraph() (*GraphSlice, error) {
	structural, err := s.ReadStructural()
	if err != nil {
		return nil, fmt.Errorf("read structural: %w", err)
	}
	history, err := s.ReadHistory()
	if err != nil {
		return nil, fmt.Errorf("read history: %w", err)
	}
	semantic, err := s.ReadSemantic()
	if err != nil {
		return nil, fmt.Errorf("read semantic: %w", err)
	}

	out := &GraphSlice{}
	seenNodes := make(map[string]struct{})
	seenEdges := make(map[string]struct{})

	for _, slice := range []*GraphSlice{structural, history, semantic} {
		for _, n := range slice.Nodes {
			if _, dup := seenNodes[n.ID]; dup {
				continue
			}
			seenNodes[n.ID] = struct{}{}
			out.Nodes = append(out.Nodes, n)
		}
		for _, e := range slice.Edges {
			if _, dup := seenEdges[e.ID]; dup {
				continue
			}
			seenEdges[e.ID] = struct{}{}
			out.Edges = append(out.Edges, e)
		}
	}
	return out, nil
}

// readSlice loads a graph slice file; missing file returns an empty slice.
func (s *Store) readSlice(name string) (*GraphSlice, error) {
	var slice GraphSlice
	if err := s.readJSON(name, &slice); err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return &GraphSlice{}, nil
		}
		return nil, err
	}
	return &slice, nil
}

func (s *Store) writeJSON(name string, v any) error {
	if err := os.MkdirAll(s.root, 0o750); err != nil {
		return fmt.Errorf("create understand cache: %w", err)
	}
	data, err := jsonutil.MarshalIndentWithNewline(v, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal %s: %w", name, err)
	}
	target := filepath.Join(s.root, name)
	tmp := target + ".tmp"
	if err := os.WriteFile(tmp, data, 0o600); err != nil {
		return fmt.Errorf("write %s: %w", name, err)
	}
	if err := os.Rename(tmp, target); err != nil {
		return fmt.Errorf("rename %s: %w", name, err)
	}
	return nil
}

func (s *Store) readJSON(name string, v any) error {
	data, err := os.ReadFile(filepath.Join(s.root, name))
	if err != nil {
		return err
	}
	if err := unmarshalStrict(data, v); err != nil {
		return fmt.Errorf("decode %s: %w", name, err)
	}
	return nil
}

func sliceOrEmpty(s *GraphSlice) *GraphSlice {
	if s == nil {
		return &GraphSlice{Nodes: []Node{}, Edges: []Edge{}}
	}
	if s.Nodes == nil {
		s.Nodes = []Node{}
	}
	if s.Edges == nil {
		s.Edges = []Edge{}
	}
	return s
}

package graph

import (
	"bytes"
	"encoding/json"
)

// unmarshalStrict decodes JSON with DisallowUnknownFields turned off (we want
// forward-compat) but with UseNumber so manifests round-trip cleanly.
func unmarshalStrict(data []byte, v any) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	return dec.Decode(v)
}

package graph

import (
	"os"
	"path/filepath"
	"testing"
	"time"
)

func TestStore_RoundTripManifest(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	s := NewStore(dir)

	if s.Exists() {
		t.Fatalf("Exists() = true on fresh dir; want false")
	}

	in := &Manifest{
		BuildID:            "abc123",
		BuiltAt:            time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC),
		RepoFingerprint:    "deadbeef",
		StructuralStatus:   "ok",
		HistoryStatus:      "ok",
		SemanticStatus:     SemanticOK,
		SemanticProvider:   "claude-code",
		SemanticModel:      "haiku",
		SupportedLanguages: []string{"go", "markdown"},
		NodeCount:          42,
		EdgeCount:          17,
	}

	if err := s.WriteManifest(in); err != nil {
		t.Fatalf("WriteManifest: %v", err)
	}
	if !s.Exists() {
		t.Fatalf("Exists() = false after WriteManifest; want true")
	}

	out, err := s.ReadManifest()
	if err != nil {
		t.Fatalf("ReadManifest: %v", err)
	}
	if out.SchemaVersion != SchemaVersion {
		t.Errorf("SchemaVersion = %d; want %d", out.SchemaVersion, SchemaVersion)
	}
	if out.BuildID != in.BuildID {
		t.Errorf("BuildID = %q; want %q", out.BuildID, in.BuildID)
	}
	if !out.BuiltAt.Equal(in.BuiltAt) {
		t.Errorf("BuiltAt = %v; want %v", out.BuiltAt, in.BuiltAt)
	}
	if out.SemanticStatus != in.SemanticStatus {
		t.Errorf("SemanticStatus = %q; want %q", out.SemanticStatus, in.SemanticStatus)
	}
	if out.NodeCount != in.NodeCount {
		t.Errorf("NodeCount = %d; want %d", out.NodeCount, in.NodeCount)
	}
}

func TestStore_RejectsNewerSchema(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	s := NewStore(dir)

	if err := os.MkdirAll(s.Root(), 0o750); err != nil {
		t.Fatalf("MkdirAll: %v", err)
	}
	bad := []byte(`{"schema_version": 9999, "build_id": "x"}`)
	if err := os.WriteFile(filepath.Join(s.Root(), "manifest.json"), bad, 0o600); err != nil {
		t.Fatalf("WriteFile: %v", err)
	}

	if _, err := s.ReadManifest(); err == nil {
		t.Fatalf("ReadManifest: want error for newer schema")
	}
}

func TestStore_RoundTripSlices(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	s := NewStore(dir)

	structural := &GraphSlice{
		Nodes: []Node{
			{ID: "repo:.", Type: NodeRepo, Name: "."},
			{ID: "file:main.go", Type: NodeFile, Name: "main.go", Path: "main.go", Language: "go"},
			{ID: "sym:main.go:main", Type: NodeSymbol, SymbolKind: SymbolFunction, Name: "main", Path: "main.go", LineStart: 1, LineEnd: 3},
		},
		Edges: []Edge{
			{ID: "e:contains:repo:file", From: "repo:.", To: "file:main.go", Type: EdgeContains},
			{ID: "e:contains:file:sym", From: "file:main.go", To: "sym:main.go:main", Type: EdgeContains},
		},
	}
	history := &GraphSlice{
		Nodes: []Node{
			{ID: "cp:abc12345", Type: NodeCheckpoint, Name: "abc12345"},
		},
		Edges: []Edge{
			{ID: "e:touched:file:cp", From: "cp:abc12345", To: "file:main.go", Type: EdgeTouchedIn, Scope: ScopeFileOwner},
		},
	}
	semantic := &GraphSlice{
		Nodes: []Node{
			{ID: "domain:auth", Type: NodeDomain, Name: "auth"},
		},
		Edges: []Edge{
			{ID: "e:belongs:file:domain", From: "file:main.go", To: "domain:auth", Type: EdgeBelongsTo},
		},
	}

	if err := s.WriteStructural(structural); err != nil {
		t.Fatalf("WriteStructural: %v", err)
	}
	if err := s.WriteHistory(history); err != nil {
		t.Fatalf("WriteHistory: %v", err)
	}
	if err := s.WriteSemantic(semantic); err != nil {
		t.Fatalf("WriteSemantic: %v", err)
	}

	got, err := s.FusedGraph()
	if err != nil {
		t.Fatalf("FusedGraph: %v", err)
	}
	if len(got.Nodes) != 5 {
		t.Errorf("fused nodes = %d; want 5 (3 structural + 1 history + 1 semantic)", len(got.Nodes))
	}
	if len(got.Edges) != 4 {
		t.Errorf("fused edges = %d; want 4", len(got.Edges))
	}
}

func TestStore_FusedGraph_Empty(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	s := NewStore(dir)

	got, err := s.FusedGraph()
	if err != nil {
		t.Fatalf("FusedGraph on empty store: %v", err)
	}
	if len(got.Nodes) != 0 || len(got.Edges) != 0 {
		t.Errorf("FusedGraph on empty store = %d nodes / %d edges; want 0/0", len(got.Nodes), len(got.Edges))
	}
}

func TestStore_FusedGraph_DedupePrefersStructural(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	s := NewStore(dir)

	structural := &GraphSlice{
		Nodes: []Node{{ID: "file:main.go", Type: NodeFile, Name: "main.go", Path: "main.go"}},
	}
	history := &GraphSlice{
		Nodes: []Node{{ID: "file:main.go", Type: NodeFile, Name: "OVERRIDE-FROM-HISTORY"}},
	}
	if err := s.WriteStructural(structural); err != nil {
		t.Fatalf("WriteStructural: %v", err)
	}
	if err := s.WriteHistory(history); err != nil {
		t.Fatalf("WriteHistory: %v", err)
	}

	got, err := s.FusedGraph()
	if err != nil {
		t.Fatalf("FusedGraph: %v", err)
	}
	if len(got.Nodes) != 1 {
		t.Fatalf("fused nodes = %d; want 1 (deduped)", len(got.Nodes))
	}
	if got.Nodes[0].Name != "main.go" {
		t.Errorf("dedupe winner Name = %q; want %q (structural should win)", got.Nodes[0].Name, "main.go")
	}
}

func TestStore_TimelineRoundTrip(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	s := NewStore(dir)

	in := &Timeline{
		Events: []TimelineEvent{
			{At: "2026-01-01T00:00:00Z", CheckpointID: "abc12345", SessionID: "s-1", Kind: "checkpoint", NodeIDs: []string{"file:a.go"}},
			{At: "2026-01-02T00:00:00Z", CheckpointID: "def67890", SessionID: "s-2", Kind: "modified", NodeIDs: []string{"file:a.go", "file:b.go"}},
		},
	}
	if err := s.WriteTimeline(in); err != nil {
		t.Fatalf("WriteTimeline: %v", err)
	}
	out, err := s.ReadTimeline()
	if err != nil {
		t.Fatalf("ReadTimeline: %v", err)
	}
	if len(out.Events) != 2 {
		t.Fatalf("events = %d; want 2", len(out.Events))
	}
	if out.Events[0].Kind != "checkpoint" {
		t.Errorf("event[0].Kind = %q; want %q", out.Events[0].Kind, "checkpoint")
	}
	if out.Events[1].Kind != "modified" {
		t.Errorf("event[1].Kind = %q; want %q", out.Events[1].Kind, "modified")
	}
}

func TestStore_Reset(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	s := NewStore(dir)

	if err := s.WriteStructural(&GraphSlice{Nodes: []Node{{ID: "x", Type: NodeFile, Name: "x"}}}); err != nil {
		t.Fatalf("WriteStructural: %v", err)
	}
	if !dirExists(s.Root()) {
		t.Fatalf("cache dir not created")
	}
	if err := s.Reset(); err != nil {
		t.Fatalf("Reset: %v", err)
	}
	if dirExists(s.Root()) {
		t.Fatalf("cache dir still exists after Reset")
	}
	// Reset on missing dir is a no-op.
	if err := s.Reset(); err != nil {
		t.Fatalf("Reset on missing dir: %v", err)
	}
}

func dirExists(p string) bool {
	st, err := os.Stat(p)
	return err == nil && st.IsDir()
}

