169	func buildCheckpointSummaryProvider(name types.AgentName, model string) (*checkpointSummaryProvider, error) {
170		ag, err := getSummaryAgent(name)
171		if err != nil {
172			return nil, fmt.Errorf("loading summary provider %s: %w", name, err)
173		}
174	
175		textGenerator, ok := agent.AsTextGenerator(ag)
176		if !ok {
