193	// ensureSummaryProviderPresent returns an error if the named summary provider's
194	// CLI binary is not on PATH. Checks the binary directly (via exec.LookPath)
195	// rather than DetectPresence, because DetectPresence checks repo-level agent
196	// configuration — a repo using Claude Code for development can still use Codex
197	// or Gemini for summary generation as long as the binary is installed.
198	func ensureSummaryProviderPresent(_ context.Context, name types.AgentName) error {
199		ag, err := getSummaryAgent(name)
200		if err != nil {
201			return fmt.Errorf("unknown summary provider %s: %w", name, err)
202		}
203		if _, ok := agent.AsTextGenerator(ag); !ok {
204			return fmt.Errorf("agent %s does not support summary generation", name)
205		}
206		if !isSummaryProviderAvailable(name, ag) {
207			return fmt.Errorf("summary provider %q is configured but its CLI binary is not on PATH; install it or update summary_generation.provider in settings", name)
208		}
