212	func validateSummaryProvider(provider string) error {
213		name := types.AgentName(provider)
214		ag, err := getSummaryAgent(name)
215		if err != nil {
216			return fmt.Errorf("unknown summary provider %q: %w", provider, err)
217		}
218		if _, ok := agent.AsTextGenerator(ag); !ok {
219			return fmt.Errorf("agent %q does not support summary generation", provider)
220		}
221		if !isSummaryProviderAvailable(name, ag) {
222			return fmt.Errorf("summary provider %q is configured but its CLI binary is not on PATH; install it or choose another provider", provider)
223		}
224		return nil
