		t.Errorf("opening tag missing nonce attribute: %s", out)
	}
	if !strings.Contains(out, "</checkpoint>") {
		t.Errorf("closing tag missing: %s", out)
	}
	if !strings.Contains(out, "deadbeef cafe abc def") {
		t.Errorf("content missing: %s", out)
	}
}

