package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"path/filepath"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/understand/graph"
	"github.com/spf13/cobra"
)

// newUnderstandExplainCmd builds `entire understand explain <file|node>`.
//
// This is the supporting primitive — the spec says it's the detail backend for
// dashboard click-through, impact, tour, and prime. Resolution rules:
//
//   - if the argument matches an exact node ID (any prefix), return that node
//   - else if it's a file path (relative or absolute), normalize to repo-relative
//     forward-slash and look for `file:<rel>` or `ghost:<rel>`
//
// Symbol-level checkpoint attribution is not yet emitted by the build pipeline
// (history fuse is file-owner only); rendering surfaces the "(file-level
// inferred)" qualifier on every checkpoint→symbol relationship and never
// conflates the two scopes in a single rendered string.
func newUnderstandExplainCmd() *cobra.Command {
	var jsonOut bool

	cmd := &cobra.Command{
		Use:   "explain <file|node>",
		Short: "Explain a file or graph node and surface its checkpoint trail",
		Long: `Resolve a file path or node ID and print structural identity plus the most
recent checkpoints that shaped it.

Examples:
  entire understand explain main.go
  entire understand explain file:cmd/entire/cli/root.go
  entire understand explain sym:cmd/entire/cli/understand_status.go:newUnderstandStatusCmd

Use --json for a stable shape suitable for scripting.`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return runUnderstandExplain(cmd.Context(), cmd.OutOrStdout(), args[0], jsonOut)
		},
	}
	cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit JSON instead of markdown")
	return cmd
}

// explainReport is the JSON shape emitted by explain --json. Stable for
// downstream commands (tour, impact, prime).
type explainReport struct {
	Node       *graph.Node       `json:"node"`
	Children   []graph.Node      `json:"children,omitempty"`
	Checkpoints []checkpointBrief `json:"checkpoints,omitempty"`
	NoCache    bool              `json:"no_cache,omitempty"`
	Reason     string            `json:"reason,omitempty"`
}

// checkpointBrief is a thin checkpoint summary inlined into explain output.
// Scope is "symbol" or "file-owner" — never mixed in a single struct value.
type checkpointBrief struct {
	ID         string `json:"id"`
	Name       string `json:"name,omitempty"`
	CreatedAt  string `json:"created_at,omitempty"`
	Agent      string `json:"agent,omitempty"`
	Scope      string `json:"scope"`
	IsTask     bool   `json:"is_task,omitempty"`
	ToolUseID  string `json:"tool_use_id,omitempty"`
}

func runUnderstandExplain(ctx context.Context, w io.Writer, target string, jsonOut bool) error {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return fmt.Errorf("resolve repo root: %w", err)
	}
	store := graph.NewStore(root)
	if !store.Exists() {
		report := explainReport{NoCache: true, Reason: "no understand cache yet — run `entire understand build`"}
		return emitExplain(w, report, jsonOut)
	}

	fused, err := store.FusedGraph()
	if err != nil {
		return fmt.Errorf("read fused graph: %w", err)
	}

	node, err := resolveExplainNode(fused, target, root)
	if err != nil {
		return err
	}

	report := explainReport{Node: node}
	report.Children = collectChildren(fused, node.ID)
	report.Checkpoints = collectCheckpoints(fused, node.ID)
	return emitExplain(w, report, jsonOut)
}

func emitExplain(w io.Writer, r explainReport, jsonOut bool) error {
	if jsonOut {
		data, err := jsonutil.MarshalIndentWithNewline(r, "", "  ")
		if err != nil {
			return fmt.Errorf("marshal explain: %w", err)
		}
		if _, err := w.Write(data); err != nil {
			return fmt.Errorf("write explain JSON: %w", err)
		}
		return nil
	}
	if r.NoCache {
		fmt.Fprintf(w, "no understand cache yet — run `entire understand build`\n")
		return nil
	}

	n := r.Node
	fmt.Fprintf(w, "# %s\n\n", n.ID)
	fmt.Fprintf(w, "- type: %s\n", n.Type)
	if n.SymbolKind != "" {
		fmt.Fprintf(w, "- symbol_kind: %s\n", n.SymbolKind)
	}
	if n.Path != "" {
		fmt.Fprintf(w, "- path: %s\n", n.Path)
	}
	if n.Language != "" {
		fmt.Fprintf(w, "- language: %s\n", n.Language)
	}
	if n.LineStart > 0 || n.LineEnd > 0 {
		fmt.Fprintf(w, "- lines: %d-%d\n", n.LineStart, n.LineEnd)
	}
	if removed, _ := n.Attrs["removed"].(bool); removed {
		fmt.Fprintf(w, "- status: REMOVED (file no longer in working tree)\n")
	}

	if len(r.Children) > 0 {
		fmt.Fprintf(w, "\n## Contains (%d)\n\n", len(r.Children))
		for _, c := range r.Children {
			label := string(c.Type)
			if c.SymbolKind != "" {
				label = fmt.Sprintf("%s/%s", c.Type, c.SymbolKind)
			}
			fmt.Fprintf(w, "- %s `%s`", label, c.Name)
			if c.LineStart > 0 {
				fmt.Fprintf(w, " (lines %d-%d)", c.LineStart, c.LineEnd)
			}
			fmt.Fprintln(w)
		}
	}

	if len(r.Checkpoints) > 0 {
		fmt.Fprintf(w, "\n## Checkpoint trail (%d)\n\n", len(r.Checkpoints))
		for _, cp := range r.Checkpoints {
			qualifier := ""
			if cp.Scope == string(graph.ScopeFileOwner) {
				qualifier = " _(file-level inferred)_"
			}
			fmt.Fprintf(w, "- `%s`%s", cp.ID, qualifier)
			if cp.CreatedAt != "" {
				fmt.Fprintf(w, " — %s", cp.CreatedAt)
			}
			if cp.Agent != "" {
				fmt.Fprintf(w, " _(%s)_", cp.Agent)
			}
			if cp.IsTask {
				fmt.Fprintf(w, " [task]")
			}
			fmt.Fprintln(w)
		}
	} else {
		fmt.Fprintf(w, "\n_No checkpoint trail yet._\n")
	}
	return nil
}

func resolveExplainNode(fused *graph.Slice, target, repoRoot string) (*graph.Node, error) {
	target = strings.TrimSpace(target)
	if target == "" {
		return nil, errors.New("explain: empty target")
	}

	// Exact node-ID match first.
	for i, n := range fused.Nodes {
		if n.ID == target {
			return &fused.Nodes[i], nil
		}
	}

	// File path resolution: normalize relative to repo root, prefer file:
	// then ghost: prefix.
	rel := normalizeExplainPath(target, repoRoot)
	for _, prefix := range []string{"file:", "ghost:"} {
		want := prefix + rel
		for i, n := range fused.Nodes {
			if n.ID == want {
				return &fused.Nodes[i], nil
			}
		}
	}

	// Last-resort symbol resolution: if target looks like `path/to/file.go:Symbol`,
	// try sym:<path>:<symbol>.
	if strings.Contains(target, ":") && !strings.HasPrefix(target, "sym:") {
		want := "sym:" + rel
		for i, n := range fused.Nodes {
			if n.ID == want {
				return &fused.Nodes[i], nil
			}
		}
	}

	return nil, fmt.Errorf("explain: no node matches %q (try `entire understand build` or pass an exact node ID)", target)
}

// normalizeExplainPath converts the user-facing argument into a repo-relative
// forward-slash path matching what the index emits. Absolute paths under
// repoRoot are made relative; anything outside the repo is returned as-is so
// resolution simply fails to find a match.
func normalizeExplainPath(p, repoRoot string) string {
	p = strings.TrimSpace(p)
	p = strings.ReplaceAll(p, "\\", "/")

	if filepath.IsAbs(p) {
		if rel, err := filepath.Rel(repoRoot, p); err == nil && !strings.HasPrefix(rel, "..") {
			return filepath.ToSlash(rel)
		}
		return p
	}

	// Strip leading "./".
	p = strings.TrimPrefix(p, "./")
	return p
}

func collectChildren(fused *graph.Slice, nodeID string) []graph.Node {
	byID := make(map[string]*graph.Node, len(fused.Nodes))
	for i := range fused.Nodes {
		byID[fused.Nodes[i].ID] = &fused.Nodes[i]
	}
	children := []graph.Node{}
	for _, e := range fused.Edges {
		if e.Type != graph.EdgeContains || e.From != nodeID {
			continue
		}
		if c, ok := byID[e.To]; ok {
			children = append(children, *c)
		}
	}
	sort.Slice(children, func(i, j int) bool { return children[i].ID < children[j].ID })
	return children
}

func collectCheckpoints(fused *graph.Slice, nodeID string) []checkpointBrief {
	byID := make(map[string]*graph.Node, len(fused.Nodes))
	for i := range fused.Nodes {
		byID[fused.Nodes[i].ID] = &fused.Nodes[i]
	}

	out := []checkpointBrief{}
	seen := map[string]struct{}{}

	addCheckpointEdge := func(cpNodeID string, scope graph.Scope) {
		cp, ok := byID[cpNodeID]
		if !ok || cp.Type != graph.NodeCheckpoint {
			return
		}
		if _, dup := seen[cpNodeID]; dup {
			return
		}
		seen[cpNodeID] = struct{}{}
		brief := checkpointBrief{
			ID:    cp.Name,
			Name:  cp.Name,
			Scope: string(scope),
		}
		if at, _ := cp.Attrs["created_at"].(string); at != "" {
			brief.CreatedAt = at
		}
		if ag, _ := cp.Attrs["agent"].(string); ag != "" {
			brief.Agent = ag
		}
		if isTask, _ := cp.Attrs["is_task"].(bool); isTask {
			brief.IsTask = true
		}
		if tu, _ := cp.Attrs["tool_use_id"].(string); tu != "" {
			brief.ToolUseID = tu
		}
		out = append(out, brief)
	}

	// Direct touched_in edges: cp -> file/ghost.
	for _, e := range fused.Edges {
		if e.Type != graph.EdgeTouchedIn {
			continue
		}
		if e.To == nodeID {
			addCheckpointEdge(e.From, e.Scope)
		}
	}

	// For symbol nodes, also follow file-owner: walk up to the parent file
	// and collect that file's checkpoints, but mark them ScopeFileOwner so
	// we don't conflate the scopes.
	if me := byID[nodeID]; me != nil && me.Type == graph.NodeSymbol && me.Path != "" {
		fileID := "file:" + me.Path
		for _, e := range fused.Edges {
			if e.Type != graph.EdgeTouchedIn || e.To != fileID {
				continue
			}
			addCheckpointEdge(e.From, graph.ScopeFileOwner)
		}
	}

	// Most recent first.
	sort.SliceStable(out, func(i, j int) bool {
		return out[i].CreatedAt > out[j].CreatedAt
	})
	return out
}

