func REDACTED(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	seedExplainCache(t, dir)
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()

	var buf bytes.Buffer
	if err := runUnderstandExplain(context.Background(), &buf, "sym:cmd/main.go:main", true); err != nil {
		t.Fatalf("runUnderstandExplain: %v", err)
	}
	var got explainReport
	if err := json.Unmarshal(buf.Bytes(), &got); err != nil {
		t.Fatalf("decode JSON: %v\nraw=%s", err, buf.String())
	}
	if got.Node == nil {
		t.Fatal("Node nil")
	}
	if got.Node.Type != graph.NodeSymbol {
		t.Errorf("Node.Type=%q; want %q", got.Node.Type, graph.NodeSymbol)
	}
	if got.Node.SymbolKind != graph.SymbolFunction {
		t.Errorf("Node.SymbolKind=%q; want %q", got.Node.SymbolKind, graph.SymbolFunction)
	}
	// Symbol inherits checkpoints via file-owner scope only.
	if len(got.Checkpoints) != 1 {
		t.Fatalf("Checkpoints=%d; want 1", len(got.Checkpoints))
	}
	if got.Checkpoints[0].Scope != string(graph.ScopeFileOwner) {
		t.Errorf("Scope=%q; want %q", got.Checkpoints[0].Scope, graph.ScopeFileOwner)
	}
	if got.Checkpoints[0].Agent != "claude-code" {
		t.Errorf("Agent=%q; want claude-code", got.Checkpoints[0].Agent)
	}
}

