// normalizeExplainPath converts the user-facing argument into a repo-relative
// forward-slash path matching what the index emits. Absolute paths under
// repoRoot are made relative; anything outside the repo is returned as-is so
// resolution simply fails to find a match.
func normalizeExplainPath(p, repoRoot string) string {
	p = strings.TrimSpace(p)
	p = strings.ReplaceAll(p, "\\", "/")

	if filepath.IsAbs(p) {
		if rel, err := filepath.Rel(repoRoot, p); err == nil && !strings.HasPrefix(rel, "..") {
			return filepath.ToSlash(rel)
		}
		return p
	}

	// Strip leading "./".
	p = strings.TrimPrefix(p, "./")
	return p
}

